  "deptBanner": "https://lh3.googleusercontent.com/pw/AP1GczPvYZzAvytNNYz4mM16tKTiA45vSTjPLR8whH4z7nsuuFZVPsIV1CO0wjc8xCINw7Gmm3hzGWzSw4JY55A4lQfzjBgaCx7Antc40F6yU0YHA0yZKWP2RCz1jae8O8dWp4xdxEgPOkEzW96qX4kSZWQdzA=w1654-h702-s-no-gm?authuser=0",
  "imgSrc": "https://lh3.googleusercontent.com/pw/AP1GczM6TbLOkg6n7hVM0yf0ZLw68im5Eh-ipad_j0GkxVsFqhkJNKRCZ6JL7WIV6soolt3Gw2WCUXll6y-0UcylX4NbRJw4mcXLo_IhWXVzHkkQZ_09WI21y_fEviHYzCwN4rc9hmW3hwPmHArsV5rwvaA4vA=w1595-h1595-s-no-gm?authuser=0",
  "image": "https://lh3.googleusercontent.com/pw/AP1GczM6TbLOkg6n7hVM0yf0ZLw68im5Eh-ipad_j0GkxVsFqhkJNKRCZ6JL7WIV6soolt3Gw2WCUXll6y-0UcylX4NbRJw4mcXLo_IhWXVzHkkQZ_09WI21y_fEviHYzCwN4rc9hmW3hwPmHArsV5rwvaA4vA=w1595-h1595-s-no-gm?authuser=0",
